<script setup>
import { reactive, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useI18n } from 'vue-i18n';
import { fetchOperationalTickets } from '../api/admin-operations'; import { ticketCategories, ticketPriorities, ticketStatuses } from '../utils/support'; import { formatDate } from '../utils/catalog';
import PageHeading from '../components/ui/PageHeading.vue'; import BaseAlert from '../components/ui/BaseAlert.vue'; import LoadingState from '../components/ui/LoadingState.vue'; import EmptyState from '../components/ui/EmptyState.vue'; import PaginationNav from '../components/ui/PaginationNav.vue'; import OperationStatusBadge from '../components/admin/OperationStatusBadge.vue';
const route = useRoute(); const router = useRouter(); const { t, locale } = useI18n(); const supportArea = route.path.startsWith('/sales-support'); const listName = supportArea ? 'support.tickets' : 'admin.tickets.index'; const detailName = supportArea ? 'support.tickets.show' : 'admin.tickets.show';
const filters = reactive({ status: '', category: '', priority: '', assigned_to: '', created_from: '', created_to: '' }); const items = ref([]); const meta = ref(null); const loading = ref(true); const error = ref(null); let sequence = 0;
async function load() { const current = ++sequence; loading.value = true; error.value = null; Object.keys(filters).forEach((key) => { filters[key] = String(route.query[key] ?? ''); }); try { const result = await fetchOperationalTickets({ page: Number(route.query.page) || 1, ...Object.fromEntries(Object.entries(filters).filter(([, value]) => value !== '')) }); if (current === sequence) { items.value = result.items; meta.value = result.meta; } } catch (failure) { if (current === sequence) error.value = failure; } finally { if (current === sequence) loading.value = false; } }
watch(() => route.query, load, { immediate: true, deep: true });
function apply() { router.push({ name: listName, query: Object.fromEntries(Object.entries(filters).filter(([, value]) => value !== '')) }); }
function page(value) { router.push({ name: listName, query: { ...route.query, page: value } }); }
</script>
<template><div class="space-y-6" :dir="locale === 'ar' ? 'rtl' : 'ltr'"><PageHeading :title="t('operations.support')" /><form class="grid gap-3 rounded-3xl border bg-white p-4 sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="apply"><label class="sr-only" for="ticket-status-filter">{{ t('operations.status') }}</label><select id="ticket-status-filter" v-model="filters.status" class="min-h-11 rounded-xl border px-3"><option value="">{{ t('operations.all') }}</option><option v-for="value in ticketStatuses" :key="value" :value="value">{{ t(`operations.ticketStatus.${value}`) }}</option></select><label class="sr-only" for="ticket-category-filter">{{ t('operations.category') }}</label><select id="ticket-category-filter" v-model="filters.category" class="min-h-11 rounded-xl border px-3"><option value="">{{ t('operations.all') }}</option><option v-for="value in ticketCategories" :key="value" :value="value">{{ t(`operations.ticketCategory.${value}`) }}</option></select><label class="sr-only" for="ticket-priority-filter">{{ t('operations.priority') }}</label><select id="ticket-priority-filter" v-model="filters.priority" class="min-h-11 rounded-xl border px-3"><option value="">{{ t('operations.all') }}</option><option v-for="value in ticketPriorities" :key="value" :value="value">{{ t(`operations.ticketPriority.${value}`) }}</option></select><label class="sr-only" for="ticket-assignee-filter">{{ t('operations.assignmentId') }}</label><input id="ticket-assignee-filter" v-model="filters.assigned_to" type="number" min="1" class="min-h-11 rounded-xl border px-3" :placeholder="t('operations.assignmentId')"><label class="sr-only" for="ticket-from">{{ t('operations.createdFrom') }}</label><input id="ticket-from" v-model="filters.created_from" type="date" class="min-h-11 rounded-xl border px-3"><label class="sr-only" for="ticket-to">{{ t('operations.createdTo') }}</label><input id="ticket-to" v-model="filters.created_to" type="date" class="min-h-11 rounded-xl border px-3"><button type="submit" class="min-h-11 rounded-xl bg-brand px-5 font-bold text-white">{{ t('operations.filter') }}</button></form><LoadingState v-if="loading" /><BaseAlert v-else-if="error" tone="danger">{{ t('operations.loadError') }} <button class="underline" @click="load">{{ t('operations.retry') }}</button></BaseAlert><EmptyState v-else-if="!items.length" :title="t('operations.empty')" /><div v-else class="grid gap-3"><RouterLink v-for="ticket in items" :key="ticket.id" :to="{ name: detailName, params: { id: ticket.id } }" class="flex flex-wrap items-center justify-between gap-3 rounded-2xl border bg-white p-5 hover:border-brand"><div><p class="font-black"><bdi>{{ ticket.ticket_number }}</bdi> · {{ ticket.subject }}</p><p class="text-sm text-slate-600">{{ ticket.student?.name }} · {{ t(`operations.ticketCategory.${ticket.category}`) }} · {{ t(`operations.ticketPriority.${ticket.priority}`) }}</p><p class="text-xs text-slate-500">{{ formatDate(ticket.updated_at, locale) }}</p></div><OperationStatusBadge group="ticketStatus" :status="ticket.status" /></RouterLink></div><PaginationNav v-if="!loading && !error && meta?.last_page > 1" :current-page="meta.current_page" :last-page="meta.last_page" @change="page" /></div></template>
